import { Response, NextFunction } from 'express';
import { AuthenticatedRequest } from '../middleware/auth.middleware';
import { ComplaintService } from '../services/complaint.service';
import { StorageUtil } from '../utils/storage.util';
import { CreateComplaintSchema } from '../models/schemas';
import { z } from 'zod';

export class ComplaintController {
  static async create(req: AuthenticatedRequest, res: Response, next: NextFunction): Promise<void> {
    try {
      const files = req.files as Express.Multer.File[] | undefined;
      const attachments = (files || []).map(f => ({
        fileName: f.filename,
        originalName: f.originalname,
        mimeType: f.mimetype,
        fileSize: f.size,
        fileUrl: StorageUtil.getPublicUrl(f.filename),
      }));

      // Parse and validate with Zod CreateComplaintSchema
      const rawInput = {
        categoryId: req.body.categoryId,
        title: req.body.title,
        description: req.body.description,
        location: req.body.location,
        priority: req.body.priority || undefined,
        latitude: req.body.latitude ? parseFloat(req.body.latitude) : undefined,
        longitude: req.body.longitude ? parseFloat(req.body.longitude) : undefined,
      };

      const validatedInput = CreateComplaintSchema.parse(rawInput);

      const complaint = await ComplaintService.createComplaint(
        req.user!,
        validatedInput,
        attachments,
        req.ip
      );

      res.status(201).json({
        success: true,
        message: 'Complaint created successfully',
        data: { complaint },
      });
    } catch (error) {
      if (error instanceof z.ZodError) {
        const validationErrors = error.errors.map(err => ({
          field: err.path.join('.'),
          message: err.message,
        }));
        res.status(400).json({
          success: false,
          message: validationErrors[0]?.message || 'Input validation failed',
          errorCode: 'VALIDATION_ERROR',
          errors: validationErrors,
        });
        return;
      }
      next(error);
    }
  }

  static async list(req: AuthenticatedRequest, res: Response, next: NextFunction): Promise<void> {
    try {
      const filters = {
        citizenId: req.query.citizenId as string | undefined,
        assignedStaffId: req.query.assignedStaffId as string | undefined,
        departmentId: req.query.departmentId as string | undefined,
        categoryId: req.query.categoryId as string | undefined,
        status: req.query.status as string | undefined,
        priority: req.query.priority as string | undefined,
        search: req.query.search as string | undefined,
        isOverdue: req.query.isOverdue === 'true',
        page: req.query.page ? parseInt(req.query.page as string, 10) : 1,
        limit: req.query.limit ? parseInt(req.query.limit as string, 10) : 20,
        sortBy: req.query.sortBy as string | undefined,
        sortOrder: (req.query.sortOrder as 'asc' | 'desc') || 'desc',
      };

      const result = await ComplaintService.listComplaints(req.user!, filters);

      res.status(200).json({
        success: true,
        message: 'Complaints retrieved successfully',
        data: result,
      });
    } catch (error) {
      next(error);
    }
  }

  static async getById(req: AuthenticatedRequest, res: Response, next: NextFunction): Promise<void> {
    try {
      const complaint = await ComplaintService.getComplaintById(req.params.id, req.user!);
      res.status(200).json({
        success: true,
        message: 'Complaint details retrieved successfully',
        data: { complaint },
      });
    } catch (error) {
      next(error);
    }
  }

  static async updateStatus(req: AuthenticatedRequest, res: Response, next: NextFunction): Promise<void> {
    try {
      const complaint = await ComplaintService.updateComplaintStatus(
        req.params.id,
        req.user!,
        req.body,
        req.ip
      );

      res.status(200).json({
        success: true,
        message: `Complaint status successfully updated to ${req.body.status}`,
        data: { complaint },
      });
    } catch (error) {
      next(error);
    }
  }

  static async assign(req: AuthenticatedRequest, res: Response, next: NextFunction): Promise<void> {
    try {
      const complaint = await ComplaintService.assignStaff(
        req.params.id,
        req.body.staffId,
        req.user!,
        req.body.notes,
        req.ip
      );

      res.status(200).json({
        success: true,
        message: 'Staff assigned to complaint successfully',
        data: { complaint },
      });
    } catch (error) {
      next(error);
    }
  }
}

import prisma from '../prisma';
import { ComplaintRepository, ComplaintFilterParams } from '../repositories/complaint.repository';
import { DepartmentRepository } from '../repositories/department.repository';
import { AuditRepository } from '../repositories/audit.repository';
import { NotificationRepository } from '../repositories/notification.repository';
import { SLAUtil, PriorityLevel } from '../utils/sla.util';
import { CreateComplaintInput, UpdateStatusInput } from '../models/schemas';
import { TokenPayload } from '../utils/jwt.util';

export class ComplaintService {
  /**
   * Create a new complaint with category lookup, SLA calculation, notification and audit logging.
   */
  static async createComplaint(
    citizen: TokenPayload,
    input: CreateComplaintInput,
    attachments: Array<{ fileName: string; originalName: string; mimeType: string; fileSize: number; fileUrl: string }> = [],
    ipAddress?: string
  ) {
    const category = await DepartmentRepository.findCategoryById(input.categoryId);
    if (!category) {
      const error: any = new Error(`Complaint Category with ID [${input.categoryId}] not found.`);
      error.statusCode = 404;
      error.errorCode = 'CATEGORY_NOT_FOUND';
      throw error;
    }

    const priority = (input.priority || category.defaultPriority) as PriorityLevel;
    const expectedResolutionDate = SLAUtil.calculateExpectedResolutionDate(priority);

    const complaint = await ComplaintRepository.create({
      citizenId: citizen.userId,
      categoryId: category.id,
      departmentId: category.departmentId,
      title: input.title,
      description: input.description,
      location: input.location,
      latitude: input.latitude,
      longitude: input.longitude,
      priority,
      expectedResolutionDate,
    });

    // Link attachments if any
    if (attachments.length > 0) {
      await prisma.attachment.createMany({
        data: attachments.map(att => ({
          complaintId: complaint.id,
          fileName: att.fileName,
          originalName: att.originalName,
          mimeType: att.mimeType,
          fileSize: att.fileSize,
          fileUrl: att.fileUrl,
          uploadedById: citizen.userId,
        })),
      });
    }

    // Create Notification for Citizen
    await NotificationRepository.create({
      userId: citizen.userId,
      complaintId: complaint.id,
      title: 'Complaint Registered Successfully',
      message: `Your complaint #${complaint.complaintNumber} ("${complaint.title}") has been registered with ${category.name}. Expected resolution by ${expectedResolutionDate.toLocaleDateString()}.`,
    });

    // Create Audit Log
    await AuditRepository.log({
      userId: citizen.userId,
      action: 'CREATE_COMPLAINT',
      entity: 'COMPLAINT',
      entityId: complaint.id,
      details: {
        complaintNumber: complaint.complaintNumber,
        category: category.name,
        priority,
        expectedResolutionDate,
        attachmentsCount: attachments.length,
      },
      ipAddress,
    });

    return this.getComplaintById(complaint.id, citizen);
  }

  /**
   * Fetch a single complaint by ID with RBAC isolation and SLA status metadata.
   */
  static async getComplaintById(id: string, user: TokenPayload) {
    const complaint = await ComplaintRepository.findById(id);
    if (!complaint) {
      const error: any = new Error(`Complaint #${id} not found.`);
      error.statusCode = 404;
      error.errorCode = 'COMPLAINT_NOT_FOUND';
      throw error;
    }

    // Role-based isolation check
    if (user.role === 'CITIZEN' && complaint.citizenId !== user.userId) {
      const error: any = new Error('Access denied: You do not have permission to view this complaint.');
      error.statusCode = 403;
      error.errorCode = 'FORBIDDEN';
      throw error;
    }

    const slaInfo = SLAUtil.getSlaStatus(
      complaint.expectedResolutionDate,
      complaint.status,
      complaint.resolvedDate
    );

    return {
      ...complaint,
      slaInfo,
    };
  }

  /**
   * List complaints with filtering and pagination.
   */
  static async listComplaints(user: TokenPayload, filters: ComplaintFilterParams) {
    const params: ComplaintFilterParams = { ...filters };

    // Strict RBAC filtering
    if (user.role === 'CITIZEN') {
      params.citizenId = user.userId;
    } else if (user.role === 'STAFF') {
      if (!filters.assignedStaffId && !filters.departmentId && user.departmentId) {
        params.departmentId = user.departmentId;
      }
    }

    const result = await ComplaintRepository.findManyWithFilters(params);

    const complaintsWithSla = result.complaints.map(c => ({
      ...c,
      slaInfo: SLAUtil.getSlaStatus(c.expectedResolutionDate, c.status, c.resolvedDate),
    }));

    return {
      ...result,
      complaints: complaintsWithSla,
    };
  }

  /**
   * Update complaint status with strict state machine validation and citizen alert.
   */
  static async updateComplaintStatus(
    id: string,
    user: TokenPayload,
    input: UpdateStatusInput,
    ipAddress?: string
  ) {
    const complaint = await ComplaintRepository.findById(id);
    if (!complaint) {
      const error: any = new Error(`Complaint #${id} not found.`);
      error.statusCode = 404;
      error.errorCode = 'COMPLAINT_NOT_FOUND';
      throw error;
    }

    // Validation of state machine transition
    const validTransitions: Record<string, string[]> = {
      SUBMITTED: ['ACKNOWLEDGED', 'ASSIGNED', 'REJECTED'],
      ACKNOWLEDGED: ['ASSIGNED', 'IN_PROGRESS', 'REJECTED'],
      ASSIGNED: ['IN_PROGRESS', 'RESOLVED', 'REJECTED'],
      IN_PROGRESS: ['RESOLVED', 'REJECTED'],
      RESOLVED: ['CLOSED'],
      REJECTED: [],
      CLOSED: [],
    };

    const allowedNext = validTransitions[complaint.status] || [];
    if (!allowedNext.includes(input.status)) {
      const error: any = new Error(
        `Invalid status transition from ${complaint.status} to ${input.status}. Allowed: [${allowedNext.join(', ')}]`
      );
      error.statusCode = 400;
      error.errorCode = 'INVALID_STATUS_TRANSITION';
      throw error;
    }

    const updated = await ComplaintRepository.updateStatus(
      complaint.id,
      input.status,
      user.userId,
      input.remarks,
      input.rejectionReason
    );

    // Notify citizen about status change
    await NotificationRepository.create({
      userId: complaint.citizenId,
      complaintId: complaint.id,
      title: `Status Updated: #${complaint.complaintNumber}`,
      message: `Your complaint #${complaint.complaintNumber} is now ${input.status}. ${input.remarks ? `Note: ${input.remarks}` : ''}`,
    });

    // Audit log
    await AuditRepository.log({
      userId: user.userId,
      action: 'UPDATE_STATUS',
      entity: 'COMPLAINT',
      entityId: complaint.id,
      details: {
        from: complaint.status,
        to: input.status,
        remarks: input.remarks,
        rejectionReason: input.rejectionReason,
      },
      ipAddress,
    });

    return this.getComplaintById(complaint.id, user);
  }

  /**
   * Assign staff to complaint.
   */
  static async assignStaff(
    complaintId: string,
    staffId: string,
    assignedBy: TokenPayload,
    notes?: string,
    ipAddress?: string
  ) {
    const complaint = await ComplaintRepository.findById(complaintId);
    if (!complaint) {
      const error: any = new Error(`Complaint #${complaintId} not found.`);
      error.statusCode = 404;
      error.errorCode = 'COMPLAINT_NOT_FOUND';
      throw error;
    }

    const updated = await ComplaintRepository.assignStaff(
      complaint.id,
      staffId,
      assignedBy.userId,
      notes
    );

    // Notify assigned staff
    await NotificationRepository.create({
      userId: staffId,
      complaintId: complaint.id,
      title: `New Assignment: #${complaint.complaintNumber}`,
      message: `You have been assigned complaint #${complaint.complaintNumber}: "${complaint.title}".`,
    });

    // Notify citizen
    await NotificationRepository.create({
      userId: complaint.citizenId,
      complaintId: complaint.id,
      title: `Staff Assigned: #${complaint.complaintNumber}`,
      message: `A municipal technician has been assigned to investigate your complaint.`,
    });

    // Audit log
    await AuditRepository.log({
      userId: assignedBy.userId,
      action: 'ASSIGN_STAFF',
      entity: 'COMPLAINT',
      entityId: complaint.id,
      details: { staffId, notes },
      ipAddress,
    });

    return this.getComplaintById(complaint.id, assignedBy);
  }
}

import prisma from '../prisma';
import { Complaint, Prisma } from '@prisma/client';

export interface ComplaintFilterParams {
  citizenId?: string;
  assignedStaffId?: string;
  departmentId?: string;
  categoryId?: string;
  status?: string;
  priority?: string;
  search?: string;
  isOverdue?: boolean;
  page?: number;
  limit?: number;
  sortBy?: string;
  sortOrder?: 'asc' | 'desc';
}

export class ComplaintRepository {
  static async generateNextComplaintNumber(): Promise<string> {
    const count = await prisma.complaint.count();
    const sequence = 1000 + count + 1;
    return `C-${sequence}`;
  }

  static async create(data: {
    citizenId: string;
    categoryId: string;
    departmentId: string;
    title: string;
    description: string;
    location: string;
    latitude?: number | null;
    longitude?: number | null;
    priority: string;
    expectedResolutionDate: Date;
  }): Promise<Complaint> {
    const complaintNumber = await this.generateNextComplaintNumber();

    return prisma.$transaction(async (tx) => {
      const complaint = await tx.complaint.create({
        data: {
          complaintNumber,
          citizenId: data.citizenId,
          categoryId: data.categoryId,
          departmentId: data.departmentId,
          title: data.title,
          description: data.description,
          location: data.location,
          latitude: data.latitude,
          longitude: data.longitude,
          priority: data.priority,
          status: 'SUBMITTED',
          expectedResolutionDate: data.expectedResolutionDate,
        },
        include: {
          category: true,
          department: true,
          citizen: { select: { id: true, name: true, email: true, phone: true } },
          attachments: true,
        },
      });

      // Create initial status history
      await tx.complaintStatusHistory.create({
        data: {
          complaintId: complaint.id,
          oldStatus: null,
          newStatus: 'SUBMITTED',
          changedById: data.citizenId,
          remarks: 'Complaint registered by citizen',
        },
      });

      return complaint;
    });
  }

  static async findById(id: string): Promise<any | null> {
    return prisma.complaint.findFirst({
      where: {
        OR: [{ id }, { complaintNumber: id }],
      },
      include: {
        category: true,
        department: true,
        citizen: { select: { id: true, name: true, email: true, phone: true } },
        assignedStaff: { select: { id: true, name: true, email: true, phone: true } },
        attachments: { include: { uploadedBy: { select: { id: true, name: true } } } },
        statusHistory: {
          include: { changedBy: { select: { id: true, name: true, role: true } } },
          orderBy: { createdAt: 'asc' },
        },
        assignments: {
          include: {
            staff: { select: { id: true, name: true, email: true } },
            assignedBy: { select: { id: true, name: true } },
          },
          orderBy: { assignedAt: 'desc' },
        },
        feedback: true,
      },
    });
  }

  static async findManyWithFilters(params: ComplaintFilterParams): Promise<{
    complaints: any[];
    total: number;
    page: number;
    totalPages: number;
  }> {
    const page = params.page || 1;
    const limit = params.limit || 20;
    const skip = (page - 1) * limit;

    const where: Prisma.ComplaintWhereInput = {};

    if (params.citizenId) {
      where.citizenId = params.citizenId;
    }

    if (params.assignedStaffId) {
      where.assignedStaffId = params.assignedStaffId;
    }

    if (params.departmentId) {
      where.departmentId = params.departmentId;
    }

    if (params.categoryId) {
      where.categoryId = params.categoryId;
    }

    if (params.status) {
      where.status = params.status.toUpperCase();
    }

    if (params.priority) {
      where.priority = params.priority.toUpperCase();
    }

    if (params.isOverdue) {
      where.expectedResolutionDate = { lt: new Date() };
      where.status = { notIn: ['RESOLVED', 'CLOSED', 'REJECTED'] };
    }

    if (params.search) {
      where.OR = [
        { complaintNumber: { contains: params.search } },
        { title: { contains: params.search } },
        { description: { contains: params.search } },
        { location: { contains: params.search } },
      ];
    }

    const orderBy: Prisma.ComplaintOrderByWithRelationInput = {};
    const sortField = params.sortBy || 'createdAt';
    const sortOrder = params.sortOrder || 'desc';

    if (sortField === 'expectedResolutionDate' || sortField === 'createdAt' || sortField === 'priority') {
      (orderBy as any)[sortField] = sortOrder;
    } else {
      orderBy.createdAt = 'desc';
    }

    const [complaints, total] = await Promise.all([
      prisma.complaint.findMany({
        where,
        skip,
        take: limit,
        orderBy,
        include: {
          category: true,
          department: true,
          citizen: { select: { id: true, name: true, email: true } },
          assignedStaff: { select: { id: true, name: true, email: true } },
          attachments: true,
          feedback: true,
        },
      }),
      prisma.complaint.count({ where }),
    ]);

    return {
      complaints,
      total,
      page,
      totalPages: Math.ceil(total / limit),
    };
  }

  static async updateStatus(
    complaintId: string,
    newStatus: string,
    changedById: string,
    remarks?: string,
    rejectionReason?: string
  ): Promise<Complaint> {
    return prisma.$transaction(async (tx) => {
      const current = await tx.complaint.findUnique({ where: { id: complaintId } });
      if (!current) {
        throw new Error(`Complaint ${complaintId} not found`);
      }

      const updateData: Prisma.ComplaintUpdateInput = {
        status: newStatus,
        updatedAt: new Date(),
      };

      if (newStatus === 'RESOLVED' || newStatus === 'CLOSED') {
        updateData.resolvedDate = new Date();
      }

      if (rejectionReason) {
        updateData.rejectionReason = rejectionReason;
      }

      const updated = await tx.complaint.update({
        where: { id: complaintId },
        data: updateData,
        include: {
          category: true,
          department: true,
          citizen: { select: { id: true, name: true, email: true } },
          assignedStaff: { select: { id: true, name: true, email: true } },
          attachments: true,
        },
      });

      await tx.complaintStatusHistory.create({
        data: {
          complaintId,
          oldStatus: current.status,
          newStatus,
          changedById,
          remarks: remarks || `Status updated from ${current.status} to ${newStatus}`,
        },
      });

      return updated;
    });
  }

  static async assignStaff(
    complaintId: string,
    staffId: string,
    assignedById: string,
    notes?: string
  ): Promise<Complaint> {
    return prisma.$transaction(async (tx) => {
      const current = await tx.complaint.findUnique({ where: { id: complaintId } });
      if (!current) {
        throw new Error(`Complaint ${complaintId} not found`);
      }

      // Mark previous assignments inactive
      await tx.staffAssignment.updateMany({
        where: { complaintId, isActive: true },
        data: { isActive: false },
      });

      // Create new assignment record
      await tx.staffAssignment.create({
        data: {
          complaintId,
          staffId,
          assignedById,
          notes,
          isActive: true,
        },
      });

      const nextStatus = current.status === 'SUBMITTED' || current.status === 'ACKNOWLEDGED'
        ? 'ASSIGNED'
        : current.status;

      const updated = await tx.complaint.update({
        where: { id: complaintId },
        data: {
          assignedStaffId: staffId,
          status: nextStatus,
          updatedAt: new Date(),
        },
        include: {
          category: true,
          department: true,
          citizen: { select: { id: true, name: true, email: true } },
          assignedStaff: { select: { id: true, name: true, email: true } },
          attachments: true,
        },
      });

      if (nextStatus !== current.status) {
        await tx.complaintStatusHistory.create({
          data: {
            complaintId,
            oldStatus: current.status,
            newStatus: nextStatus,
            changedById: assignedById,
            remarks: notes || `Complaint assigned to staff member`,
          },
        });
      }

      return updated;
    });
  }

  static async delete(id: string): Promise<Complaint> {
    return prisma.complaint.delete({
      where: { id },
    });
  }
}

